export const DEFAULT_PAGE_SIZE = 10;
export const MAX_PAGE_SIZE = 50;

export type PageQuery = {
  page: number;
  pageSize: number;
};

export type PageResult<T> = {
  items: T[];
  page: number;
  pageSize: number;
  total: number;
  totalPages: number;
};

export type PageToken = number | "ellipsis";

export function parsePageQuery(searchParams: URLSearchParams): PageQuery {
  return {
    page: positiveInt(searchParams.get("page"), 1),
    pageSize: Math.min(
      positiveInt(searchParams.get("pageSize"), DEFAULT_PAGE_SIZE),
      MAX_PAGE_SIZE,
    ),
  };
}

export function paginate<T>(items: T[], query: PageQuery): PageResult<T> {
  const pageSize = Math.min(Math.max(query.pageSize, 1), MAX_PAGE_SIZE);
  const total = items.length;
  const totalPages = total === 0 ? 0 : Math.ceil(total / pageSize);
  const page = totalPages === 0 ? 1 : Math.min(Math.max(query.page, 1), totalPages);
  const start = (page - 1) * pageSize;

  return {
    items: items.slice(start, start + pageSize),
    page,
    pageSize,
    total,
    totalPages,
  };
}

export function pageTokens(
  page: number,
  totalPages: number,
  siblingCount = 1,
): PageToken[] {
  const totalNumbers = siblingCount * 2 + 5;
  if (totalPages <= totalNumbers) {
    return range(1, totalPages);
  }

  const leftSibling = Math.max(page - siblingCount, 1);
  const rightSibling = Math.min(page + siblingCount, totalPages);
  const showLeftEllipsis = leftSibling > 2;
  const showRightEllipsis = rightSibling < totalPages - 1;

  if (!showLeftEllipsis && showRightEllipsis) {
    const leftCount = 3 + siblingCount * 2;
    return [...range(1, leftCount), "ellipsis", totalPages];
  }

  if (showLeftEllipsis && !showRightEllipsis) {
    const rightCount = 3 + siblingCount * 2;
    return [1, "ellipsis", ...range(totalPages - rightCount + 1, totalPages)];
  }

  return [
    1,
    "ellipsis",
    ...range(leftSibling, rightSibling),
    "ellipsis",
    totalPages,
  ];
}

function positiveInt(value: string | null, fallback: number) {
  if (!value) return fallback;
  const parsed = Number(value);
  if (!Number.isInteger(parsed) || parsed < 1) return fallback;
  return parsed;
}

function range(start: number, end: number) {
  return Array.from({ length: end - start + 1 }, (_, index) => start + index);
}

"use client";

import { ChevronLeft, ChevronRight, MoreHorizontal } from "lucide-react";
import { Button } from "@/components/ui/button";
import { pageTokens } from "@/lib/pagination";
import { cn } from "cn";

export function Pagination({
  page,
  pageSize,
  total,
  onPageChange,
  siblingCount = 1,
  className,
}: {
  page: number;
  pageSize: number;
  total: number;
  onPageChange: (page: number) => void;
  siblingCount?: number;
  className?: string;
}) {
  if (pageSize < 1 || total <= pageSize) return null;

  const totalPages = Math.ceil(total / pageSize);
  const current = Math.min(Math.max(page, 1), totalPages);
  const tokens = pageTokens(current, totalPages, siblingCount);
  const from = (current - 1) * pageSize + 1;
  const to = Math.min(current * pageSize, total);

  return (
    <nav
      aria-label="Pagination"
      data-slot="pagination"
      className={cn(
        "flex flex-wrap items-center justify-between gap-3",
        className,
      )}
    >
      <p className="text-xs text-muted-foreground">
        {from}–{to} of {total}
      </p>
      <ul className="flex flex-wrap items-center gap-1">
        <li>
          <Button
            type="button"
            variant="outline"
            size="icon-sm"
            aria-label="Previous page"
            disabled={current <= 1}
            onClick={() => onPageChange(current - 1)}
            className="cursor-pointer"
          >
            <ChevronLeft />
          </Button>
        </li>
        {tokens.map((token, index) =>
          token === "ellipsis" ? (
            <li key={`ellipsis-${index}`}>
              <span
                aria-hidden="true"
                className="flex size-7 items-center justify-center text-muted-foreground"
              >
                <MoreHorizontal className="size-4" />
                <span className="sr-only">More pages</span>
              </span>
            </li>
          ) : (
            <li key={token}>
              <Button
                type="button"
                variant={token === current ? "default" : "ghost"}
                size="sm"
                aria-label={`Page ${token}`}
                aria-current={token === current ? "page" : undefined}
                onClick={() => {
                  if (token !== current) onPageChange(token);
                }}
                className="min-w-7 cursor-pointer px-0"
              >
                {token}
              </Button>
            </li>
          ),
        )}
        <li>
          <Button
            type="button"
            variant="outline"
            size="icon-sm"
            aria-label="Next page"
            disabled={current >= totalPages}
            onClick={() => onPageChange(current + 1)}
            className="cursor-pointer"
          >
            <ChevronRight />
          </Button>
        </li>
      </ul>
    </nav>
  );
}

