export async function listRuns(
  userId: string,
  query: PageQuery = { page: 1, pageSize: DEFAULT_PAGE_SIZE },
) {
  const firestore = db();
  const [snap, projectSnap] = await Promise.all([
    firestore.collection(COLLECTIONS.RUNS).where("userId", "==", userId).get(),
    firestore
      .collection(COLLECTIONS.PROJECTS)
      .where("userId", "==", userId)
      .limit(1)
      .get(),
  ]);

  const runs = snap.docs
    .map((doc) => toRun(doc.id, doc.data()))
    .sort((a, b) => (b.createdAt ?? "").localeCompare(a.createdAt ?? ""));
  const projectId = projectSnap.docs[0]?.id ?? "";
  const page = paginate(runs, query);
  const locked = activeRunId(runs);
  const active = locked ? runs.find((run) => run.id === locked) : undefined;

  return {
    runs: page.items,
    page: page.page,
    pageSize: page.pageSize,
    total: page.total,
    totalPages: page.totalPages,
    activeRunId: locked,
    activeStatus: active?.status ?? null,
    starting: startingNumbers(runs, projectId),
    currentTotal: projectId
      ? runs.filter((run) => run.projectId === projectId).length
      : 0,
  };
}

